widget.solution:
import numpy as np

def hedge_ratio(y, x):
    """OLS of y on x with an intercept: return (beta, alpha), each to 6 places."""
    beta, alpha = np.polyfit(x, y, 1)
    return round(float(beta), 6), round(float(alpha), 6)


def both_directions(y, x):
    """Return (beta of y on x, 1 / beta of x on y, R squared), each to 6 places."""
    b_yx = np.polyfit(x, y, 1)[0]
    b_xy = np.polyfit(y, x, 1)[0]          # the other direction
    r2 = np.corrcoef(x, y)[0, 1] ** 2
    return round(float(b_yx), 6), round(float(1 / b_xy), 6), round(float(r2), 6)
